import React from 'react';

function About() {
  return (
    <section id="about" className="about">
      <h2>About Us</h2>
      <p>We are trusted CCTV suppliers providing premium surveillance equipment across the country. Quality, reliability, and service are at the heart of what we do. Protect your spaces with the best in CCTV technology — making safety seamless for homes, businesses, and institutions alike!</p>
    </section>
  );
}

export default About;
